        // mid-cycle, `.aborted.<UTC>` post-crash) but the HTML log
        // file inside is always named with the stable base identity.
        // Mirror Get-CycleFolderIdentity in Test.Log.psm1.
        var base = parts[parts.length - 1]
          .replace(/\.incomplete$/, '')
          .replace(/\.aborted\.[^/\\]+$/, '');
