            if (lf.sequenceName) { parts.push(escHtml(t(lf.stepNumber ? 'status.failure_sequence_step' : 'status.failure_sequence', {sequence: lf.sequenceName, step: lf.stepNumber}))); }
            if (lf.errorMessage) { parts.push(escHtml(lf.errorMessage)); }
            var fcHtml = parts.join(' &middot; ');
