      "autoSeed": "status.config_field_autoseed",
      "bootDelaySeconds": "status.config_field_bootdelayseconds",
      "cachingProxyIp": "status.config_field_cachingproxyip",
      "charDelayMs": "status.config_field_chardelayms",
      "cleanupVmNamePrefixes": "status.config_field_cleanupvmnameprefixes",
      "configService": "status.config_field_configservice",
      "cycleDelaySeconds": "status.config_field_cycledelayseconds",
      "discoveryIntervalSeconds": "status.config_field_discoveryintervalseconds",
      "downloadAgentService": "status.config_field_downloadagentservice",
