      "pool": "status.config_field_pool",
      "poolStorageLocalPath": "status.config_field_poolstoragelocalpath",
      "poolStorageNetworkPath": "status.config_field_poolstoragenetworkpath",
      "poolStorageNetworkUser": "status.config_field_poolstoragenetworkuser",
      "port": "status.config_field_port",
      "preambleTimeoutSeconds": "status.config_field_preambletimeoutseconds",
      "prefetchLeadSeconds": "status.config_field_prefetchleadseconds",
