      "scanIntervalSeconds": "status.config_field_scanintervalseconds",
      "screenHistorySize": "status.config_field_screenhistorysize",
      "skipCycles": "status.config_field_skipcycles",
      "startTimeoutSeconds": "status.config_field_starttimeoutseconds",
